func SaveToFile(content, filename string) error {
	// Write the content to the specified file
	err := os.WriteFile(filename, []byte(content), 0644)
	if err != nil {
		return fmt.Errorf("failed to write to file: %w", err)
	}
	return nil
}

func GeneratePDFFromMarkdown(markdownContent, cssFilePath, outputFilePath string) error {
	const apiURL = "http://0.0.0.0:8000"

	// 1. Read the CSS file content from the provided path.
	cssContent, err := os.ReadFile(cssFilePath)
	if err != nil {
		// Return a more informative error by wrapping the original error.
		return fmt.Errorf("failed to read CSS file '%s': %w", cssFilePath, err)
	}

	// 2. Prepare the form data, which is equivalent to curl's --data-urlencode.
	// The http.PostForm function handles the URL encoding automatically.
	formData := url.Values{
		"markdown": {markdownContent},
		"css":      {string(cssContent)},
	}

	fmt.Printf("Sending request to %s to generate PDF...\n", apiURL)

	// 3. Make the HTTP POST request.
	resp, err := http.PostForm(apiURL, formData)
	if err != nil {
		return fmt.Errorf("failed to make POST request to md-to-pdf service: %w", err)
	}
	// CRITICAL: Always ensure the response body is closed to prevent resource leaks.
	defer resp.Body.Close()

	// 4. Check for a successful response status code (HTTP 200).
	if resp.StatusCode != http.StatusOK {
		// Try to read the error body from the service for better debugging.
		bodyBytes, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("md-to-pdf service returned a non-200 status: %s, body: %s", resp.Status, string(bodyBytes))
	}

	// 5. Ensure the directory for the output file exists.
	outputDir := filepath.Dir(outputFilePath)
	if err := os.MkdirAll(outputDir, 0755); err != nil {
		return fmt.Errorf("failed to create output directory '%s': %w", outputDir, err)
	}

	// 6. Create the output file.
	outputFile, err := os.Create(outputFilePath)
	if err != nil {
		return fmt.Errorf("failed to create output file '%s': %w", outputFilePath, err)
	}
	defer outputFile.Close()

	// 7. Stream the response body (the PDF data) directly into the file.
	// io.Copy is efficient for this task.
	_, err = io.Copy(outputFile, resp.Body)
	if err != nil {
		return fmt.Errorf("failed to save PDF content to file '%s': %w", outputFilePath, err)
	}

	fmt.Printf("Successfully saved PDF to %s\n", outputFilePath)
	return nil
}
